coding.solution:
#include <iostream>

using std::cout;
using std::endl;

namespace Protoss
{
    int UnitCount;
}

namespace Terran
{
    int UnitCount;
}

namespace Zerg
{
    int UnitCount;
}

int main()
{
    Protoss::UnitCount = 12;
    Terran::UnitCount = 8;
    Zerg::UnitCount = 30;

    cout << "Protoss Unit: " << Protoss::UnitCount << endl;
    cout << "Terran Unit: " << Terran::UnitCount << endl;
    cout << "Zerg Unit: " << Zerg::UnitCount << endl;

    return 0;
}
